include("shared.lua");surface.CreateFont("GRMClock3D",{font="Roboto",size=40,weight=900,extended=true});surface.CreateFont("GRMClock3DSmall",{font="Roboto",size=18,weight=600,extended=true})
function ENT:Draw()self:DrawModel();if LocalPlayer():GetPos():DistToSqr(self:GetPos())>700*700 then return end;local a=self:GetAngles();local pos=self:GetPos()+a:Forward()*3.2+a:Up()*9;local ang=Angle(a.p,a.y,a.r);ang:RotateAroundAxis(ang:Up(),90);ang:RotateAroundAxis(ang:Forward(),90);cam.Start3D2D(pos,ang,.08);draw.RoundedBox(8,-145,-55,290,110,Color(12,15,20,245));draw.SimpleText(GRM.Weather and GRM.Weather.FormatTime()or"--:--","GRMClock3D",0,-8,Color(240,245,250),TEXT_ALIGN_CENTER,TEXT_ALIGN_CENTER);draw.SimpleText(self:GetClockName(),"GRMClock3DSmall",0,31,Color(170,180,195),TEXT_ALIGN_CENTER,TEXT_ALIGN_CENTER);cam.End3D2D()end
